import { attachControl } from "@babylonjs/lite";
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";

export function attachFastOrbit(camera: ArcRotateCamera, canvas: HTMLCanvasElement, scene: SceneContext): () => void {
  const previousAngularSensibility = camera.angularSensibility;
  // The standard controls compute rotate offsets as -dx / angularSensibility.
  // Halving it doubles both the immediate drag response and the inertia glide.
  camera.angularSensibility = previousAngularSensibility / 2;

  let dispose: () => void;
  try {
    dispose = attachControl(camera, canvas, scene);
  } catch (error) {
    camera.angularSensibility = previousAngularSensibility;
    throw error;
  }

  return () => {
    try {
      dispose();
    } finally {
      camera.angularSensibility = previousAngularSensibility;
    }
  };
}

